# Search products for each requested item (paginate through all pages)
queries = {
    'CamelBak Crux 3L Reservoir': {'query':'CamelBak Crux 3L Reservoir'},
    'PlayStation 4 Pro Console': {'query':'PlayStation 4 Pro Console'},
    'Dash Mini Waffle Maker': {'query':'Dash Mini Waffle Maker'}
}

results_by_query = {}
for label, q in queries.items():
    all_results = []
    page_index = 0
    page_limit = 20
    while True:
        page = apis.amazon.search_products(query=q['query'], page_index=page_index, page_limit=page_limit)
        if not page:
            break
        all_results.extend(page)
        page_index += 1
        if page_index > 50:
            break
    results_by_query[label] = all_results
    print('---', label, 'total_results', len(all_results))
    # print up to first 5 names to inspect
    for r in all_results[:5]:
        print('sample:', r['product_id'], r['name'] if 'name' in r else r.get('product_name'), '|', r.get('price'), '| rating', r.get('rating'), '| inv', r.get('inventory_quantity'))

# Also show exact-name match counts (case-insensitive) for each query
for label, all_results in results_by_query.items():
    target = label.lower()
    exact = [r for r in all_results if r.get('name','').lower() == target]
    print('Exact matches for', label, ':', len(exact))
    for r in exact[:10]:
        print('  exact:', r['product_id'], '| price', r.get('price'), '| rating', r.get('rating'), '| inv', r.get('inventory_quantity'))

